"""Data contracts for Risk Radar using Pydantic V2."""

from datetime import datetime
from typing import List, Optional
from pydantic import BaseModel, Field, field_validator

from backend.schemas import RiskType, SourceType, Item


class Flag(BaseModel):
    """Detection result generated by LLM classification."""
    item_id: str = Field(..., description="Referenced Item ID")
    company: str = Field(..., min_length=1, description="Company ticker")
    source_url: str = Field(..., description="Direct citation source URL")
    date: datetime = Field(..., description="Event timestamp")
    risk_type: RiskType = Field(..., description="Risk category: legal, compliance, operational, noise")
    severity: int = Field(..., ge=0, le=5, description="Severity score 0 to 5 based on rubric")
    confidence: float = Field(..., ge=0.0, le=1.0, description="Model classification confidence")
    reason: str = Field(..., min_length=5, description="Structured justification strictly derived from source")
    is_simulated: bool = Field(default=False, description="Whether flag stems from simulated item")


class ItemContribution(BaseModel):
    """Calculated weight contribution of a specific item to the score."""
    item_id: str = Field(..., description="ID of contributing item")
    risk_type: RiskType = Field(..., description="Risk type")
    severity: int = Field(..., ge=0, le=5, description="Raw severity")
    age_days: float = Field(..., ge=0.0, description="Item age in days at as-of time")
    weight: float = Field(..., ge=0.0, le=1.0, description="Category type weight")
    decayed_score: float = Field(..., ge=0.0, description="severity * weight * 0.5^(age_days/7)")


class ScorePoint(BaseModel):
    """Corporate Risk Index evaluation at a specific timestamp."""
    company: str = Field(..., min_length=1, description="Company ticker")
    as_of: datetime = Field(..., description="Timestamp calculation was evaluated as-of")
    index_score: float = Field(..., ge=0.0, le=100.0, description="Rolling corporate risk index (0-100)")
    raw_s: float = Field(..., ge=0.0, description="Raw weighted severity sum S before sigmoid")
    z_score: float = Field(default=0.0, description="7-day vs 90-day complaint count z-score")
    complaint_spike_bonus: float = Field(default=0.0, ge=0.0, le=5.0, description="Spike bonus clamp(z-1, 0, 5)")
    top_contributing_items: List[ItemContribution] = Field(default_factory=list, description="Top ranked items contributing to S")
    is_simulated: bool = Field(default=False, description="True if computed using simulated events")


class Explanation(BaseModel):
    """Grounded natural language risk explanation."""
    company: str = Field(..., min_length=1, description="Company ticker")
    as_of: datetime = Field(..., description="Timestamp of evaluation")
    summary: str = Field(..., min_length=10, description="Plain-language explanation (max 2 sentences)")
    cited_source_ids: List[str] = Field(..., min_length=1, description="Database-backed source IDs referenced")
    is_simulated: bool = Field(default=False, description="True if any cited source is simulated")

    @field_validator("cited_source_ids")
    @classmethod
    def validate_cited_source_ids(cls, v: List[str]) -> List[str]:
        if not v:
            raise ValueError("Every explanation must cite at least one database source ID")
        for source_id in v:
            if not source_id.strip():
                raise ValueError("Source ID cannot be empty")
        return v
